CREATE TABLE IF NOT EXISTS diseases (disease_id TEXT, canonical_name TEXT, concise_definition TEXT, organ_system_primary TEXT, board_exam_priority TEXT, time_course TEXT, severity_or_acuity TEXT, epidemiology_summary TEXT, risk_factors_summary TEXT, pathophysiology_summary TEXT, classic_presentation_summary TEXT, key_distinguishing_features TEXT, common_board_traps TEXT, emergency_red_flags TEXT, disposition_summary TEXT, prognosis_summary TEXT, last_reviewed_date TEXT, replacement_disease_id TEXT, source_review_status TEXT, medical_review_status TEXT, deprecated TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS presentations (presentation_id TEXT, name TEXT, concise_definition TEXT, emergency_priority TEXT, initial_stabilization_summary TEXT, key_history_questions TEXT, key_exam_focus TEXT, initial_test_categories TEXT, source_review_status TEXT, medical_review_status TEXT, deprecated TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS treatments (treatment_id TEXT, name TEXT, treatment_type TEXT, treatment_category TEXT, general_description TEXT, mechanism_summary TEXT, major_contraindications TEXT, monitoring_summary TEXT, pregnancy_context TEXT, pediatric_context TEXT, renal_context TEXT, hepatic_context TEXT, emergency_role TEXT, source_review_status TEXT, medical_review_status TEXT, deprecated TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS medications (medication_id TEXT, generic_name TEXT, medication_class TEXT, mechanism_summary TEXT, major_adverse_effects_summary TEXT, major_contraindications_summary TEXT, monitoring_summary TEXT, reversal_agent_summary TEXT, pregnancy_context TEXT, renal_adjustment_context TEXT, hepatic_adjustment_context TEXT, source_review_status TEXT, medical_review_status TEXT, deprecated TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS diagnostics (diagnostic_id TEXT, name TEXT, diagnostic_type TEXT, specimen_or_modality TEXT, general_description TEXT, limitations_summary TEXT, contraindications_summary TEXT, source_review_status TEXT, medical_review_status TEXT, deprecated TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS algorithms (algorithm_id TEXT, name TEXT, triggering_presentation_id TEXT, clinical_setting TEXT, age_context TEXT, pregnancy_context TEXT, objective TEXT, starting_node_id TEXT, emergency_status TEXT, version TEXT, source_review_status TEXT, medical_review_status TEXT, deprecated TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS references (reference_id TEXT, title TEXT, organization_or_author TEXT, source_type TEXT, publication_year TEXT, url TEXT, date_accessed TEXT, relevant_topic TEXT, notes TEXT, verification_status TEXT);
CREATE TABLE IF NOT EXISTS disease_presentations (disease_presentation_id TEXT, disease_id TEXT, presentation_id TEXT, source_review_status TEXT, medical_review_status TEXT);
CREATE TABLE IF NOT EXISTS disease_treatments (disease_treatment_id TEXT, disease_id TEXT, treatment_id TEXT, role TEXT, clinical_context TEXT, sequence_order TEXT, first_line TEXT, definitive TEXT, rescue_or_escalation TEXT, unstable_patient_only TEXT, contraindication_notes TEXT, board_exam_pearl TEXT, source_review_status TEXT, medical_review_status TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS disease_differentials (differential_link_id TEXT, source_disease_id TEXT, competing_disease_id TEXT, presentation_id TEXT, similarity_reason TEXT, distinguishing_features TEXT, cannot_miss TEXT, relative_priority TEXT, age_context TEXT, rotation_context TEXT, exam_context TEXT, source_review_status TEXT, medical_review_status TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS disease_diagnostics (disease_diagnostic_id TEXT, disease_id TEXT, diagnostic_id TEXT, role TEXT, source_review_status TEXT, medical_review_status TEXT);
CREATE TABLE IF NOT EXISTS algorithm_steps (algorithm_step_id TEXT, algorithm_id TEXT, node_id TEXT, node_type TEXT, prompt_or_action TEXT, condition_expression TEXT, next_node_if_true TEXT, next_node_if_false TEXT, next_node_default TEXT, terminal_outcome TEXT, sequence_hint TEXT, explanation TEXT, source_review_status TEXT, medical_review_status TEXT);
